"use client"

import Link from "next/link"
import { FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from "react"
import {
  Activity, AlertOctagon, AlertTriangle, ArrowRight, BadgeCheck, Banknote, BriefcaseBusiness,
  Building2, CalendarClock, CheckCircle2, ChevronRight, CircleDollarSign, ClipboardCheck,
  Clock3, FileCheck2, FileLock2, FileSignature, FileText, Handshake, History, Landmark,
  Layers3, ListChecks, LockKeyhole, MessageSquare, Milestone, Plus, ReceiptText, RefreshCw,
  Scale, Search, Send, ShieldAlert, ShieldCheck, Sparkles, TrendingUp, UserCheck, Users,
  WalletCards, X, Zap,
} from "lucide-react"
import styles from "./RevenueContractWorkspace.module.css"
import { CONTRACT_NAVIGATION, CONTRACT_ROUTE_CONTRACTS } from "./route-contracts"
import type { ContractContextType, ContractExperienceKey, ContractModalKind, ContractRecord } from "./types"
import { contractMutation, useContractPortfolio } from "./useContractPortfolio"

const moneyFmt=new Intl.NumberFormat("fr-FR",{maximumFractionDigits:0})
const decimalFmt=new Intl.NumberFormat("fr-FR",{maximumFractionDigits:1})
const dateFmt=new Intl.DateTimeFormat("fr-FR",{dateStyle:"medium"})
function dh(value:unknown){const n=Number(value||0);return `${moneyFmt.format(Number.isFinite(n)?n:0)} Dh`}
function pct(value:unknown){const n=Number(value||0);return `${decimalFmt.format(Number.isFinite(n)?n:0)} %`}
function date(value:unknown){if(!value)return "—";const d=new Date(String(value));return Number.isNaN(d.getTime())?"—":dateFmt.format(d)}
function label(value:unknown){return String(value||"—").replaceAll("_"," ")}
function tone(value?:string|null){const v=String(value||"").toLowerCase();if(["active","effective","approved","fully_signed","confirmed","completed","kept","passed","realized","accepted"].includes(v))return styles.green;if(["blocked","terminated","broken","rejected","failed","overdue","critical","suspended"].includes(v))return styles.red;if(["pending","conditions_pending","signature_pending","approval_required","payment_expected","due_soon","partially_signed"].includes(v))return styles.amber;if(["activation_pending","review","internal_review","requested"].includes(v))return styles.violet;return styles.blue}

type Props={experience:ContractExperienceKey;contextId?:string|null;contextType?:ContractContextType}

type ModalMeta={title:string;subtitle:string;endpoint:string;mode?:"form"|"view"}
const MODAL_META:Record<ContractModalKind,ModalMeta>={
  "create-contract":{title:"Créer un contrat gouverné",subtitle:"Créez uniquement depuis un handoff commercial accepté et versionné.",endpoint:"/api/revenue-command-center/contract/contracts"},
  "add-section":{title:"Ajouter une section contractuelle",subtitle:"Structurez le document sans modifier les versions déjà figées.",endpoint:"/api/revenue-command-center/contract/commands"},
  "add-clause":{title:"Ajouter une clause",subtitle:"Distinguez le contenu client des notes internes sensibles.",endpoint:"/api/revenue-command-center/contract/commands"},
  "commercial-term":{title:"Ajouter une condition commerciale",subtitle:"Formalisez dates, valeur, paiement, activation ou renouvellement.",endpoint:"/api/revenue-command-center/contract/commands"},
  "add-obligation":{title:"Créer une obligation",subtitle:"Chaque engagement doit avoir un responsable, une échéance et une preuve.",endpoint:"/api/revenue-command-center/contract/obligations"},
  "add-milestone":{title:"Créer un jalon contractuel",subtitle:"Reliez le jalon à un livrable, un paiement ou une activation.",endpoint:"/api/revenue-command-center/contract/milestones"},
  "create-version":{title:"Créer une version immuable",subtitle:"Figez le contrat, les clauses, obligations et conditions exactes.",endpoint:"/api/revenue-command-center/contract/versions"},
  "compare-versions":{title:"Comparer les versions",subtitle:"Inspectez les changements contractuels et leurs conséquences.",endpoint:"",mode:"view"},
  "request-review":{title:"Demander une revue",subtitle:"Soumettez le contrat à la revue commerciale, finance, opérations ou juridique.",endpoint:"/api/revenue-command-center/contract/reviews"},
  "review-decision":{title:"Enregistrer la décision de revue",subtitle:"Documentez l’autorité, les réserves et les corrections exigées.",endpoint:"/api/revenue-command-center/contract/commands"},
  "request-approval":{title:"Demander l’approbation contractuelle",subtitle:"Présentez la version exacte, la valeur et le risque de décision.",endpoint:"/api/revenue-command-center/contract/commands"},
  "approval-decision":{title:"Décider l’approbation",subtitle:"Approuvez, rejetez ou retournez le contrat avec une justification auditable.",endpoint:"/api/revenue-command-center/contract/commands"},
  "add-signatory":{title:"Ajouter un signataire",subtitle:"Définissez son rôle, son ordre et son caractère obligatoire.",endpoint:"/api/revenue-command-center/contract/signatories"},
  "signature-request":{title:"Enregistrer une demande de signature",subtitle:"Créez une demande réelle avec échéance et canal vérifiable.",endpoint:"/api/revenue-command-center/contract/signatures"},
  "signature-evidence":{title:"Enregistrer une preuve de signature",subtitle:"Une signature n’est complète qu’après vérification de sa preuve.",endpoint:"/api/revenue-command-center/contract/signatures"},
  "signature-decline":{title:"Enregistrer un refus de signature",subtitle:"Préservez le motif, l’auteur et la conséquence contractuelle.",endpoint:"/api/revenue-command-center/contract/commands"},
  "signature-reminder":{title:"Enregistrer un rappel de signature",subtitle:"Tracez le canal, le destinataire et la nouvelle échéance.",endpoint:"/api/revenue-command-center/contract/commands"},
  "add-condition":{title:"Ajouter une condition préalable",subtitle:"Définissez la condition, son propriétaire, sa preuve et son caractère obligatoire.",endpoint:"/api/revenue-command-center/contract/conditions"},
  "verify-condition":{title:"Vérifier une condition",subtitle:"Acceptez ou rejetez la preuve avant l’effectivité.",endpoint:"/api/revenue-command-center/contract/commands"},
  "payment-terms":{title:"Définir les conditions de paiement",subtitle:"Formalisez dépôt, échéances et référence finance sans dupliquer la comptabilité.",endpoint:"/api/revenue-command-center/contract/payment-terms"},
  "payment-schedule":{title:"Créer une échéance de paiement",subtitle:"Reliez montant, date, jalon et conséquence d’activation.",endpoint:"/api/revenue-command-center/contract/payment-schedules"},
  "payment-requirement":{title:"Créer une exigence de paiement",subtitle:"Définissez le gate contractuel attendu avant activation.",endpoint:"/api/revenue-command-center/contract/commands"},
  "payment-promise":{title:"Enregistrer une promesse de paiement",subtitle:"Capturez montant, date, source et confiance sans la confondre avec un paiement confirmé.",endpoint:"/api/revenue-command-center/contract/payment-promises"},
  "promise-broken":{title:"Déclarer la promesse rompue",subtitle:"Créez immédiatement l’action de récupération et l’escalade appropriée.",endpoint:"/api/revenue-command-center/contract/commands"},
  "collection-action":{title:"Créer une action de recouvrement commercial",subtitle:"Coordonnez le suivi avec Finance et conservez la communication source.",endpoint:"/api/revenue-command-center/contract/collection-actions"},
  "finance-handoff":{title:"Soumettre le handoff Finance",subtitle:"Transférez les conditions approuvées et empêchez les doublons.",endpoint:"/api/revenue-command-center/contract/finance-handoffs"},
  "finance-decision":{title:"Décision Finance sur le handoff",subtitle:"Acceptez, demandez clarification ou rejetez avec référence précise.",endpoint:"/api/revenue-command-center/contract/commands"},
  "payment-confirmation":{title:"Enregistrer une confirmation financière",subtitle:"La confirmation exige une référence Finance ou une preuve vérifiée.",endpoint:"/api/revenue-command-center/contract/payment-confirmations"},
  "payment-discrepancy":{title:"Déclarer un écart de paiement",subtitle:"Exposez le montant attendu, confirmé et restant.",endpoint:"/api/revenue-command-center/contract/commands"},
  "evaluate-effectiveness":{title:"Évaluer l’effectivité",subtitle:"Recalculez approbations, signatures, conditions et gates de paiement.",endpoint:"/api/revenue-command-center/contract/effectiveness"},
  "evaluate-activation":{title:"Évaluer les gates d’activation",subtitle:"Aucune activation ne doit dépendre d’une simple impression visuelle.",endpoint:"/api/revenue-command-center/contract/activation/evaluate"},
  "activation-decision":{title:"Décider l’activation",subtitle:"Autorisez ou bloquez selon le résultat des gates et votre autorité.",endpoint:"/api/revenue-command-center/contract/activation/authorize"},
  "activation-override":{title:"Demander une dérogation d’activation",subtitle:"Documentez le risque, la justification, l’autorité et la preuve.",endpoint:"/api/revenue-command-center/contract/commands"},
  "operational-handoff":{title:"Créer le handoff opérationnel",subtitle:"Transmettez portée, obligations, contacts, démarrage et risques au module receveur.",endpoint:"/api/revenue-command-center/contract/operational-handoffs"},
  "handoff-acceptance":{title:"Accepter le handoff opérationnel",subtitle:"Le responsable receveur confirme la capacité, les réserves et la date de prise en charge.",endpoint:"/api/revenue-command-center/contract/commands"},
  "service-activation":{title:"Confirmer la mise en service",subtitle:"Activez uniquement après autorisation et acceptation du handoff.",endpoint:"/api/revenue-command-center/contract/commands"},
  "suspend-activation":{title:"Suspendre l’activation",subtitle:"Documentez le motif, l’impact client et le plan de rétablissement.",endpoint:"/api/revenue-command-center/contract/commands"},
  realization:{title:"Confirmer la réalisation du revenu",subtitle:"Reliez le montant à une preuve Finance autoritative et empêchez les doublons.",endpoint:"/api/revenue-command-center/contract/realization"},
  "reverse-realization":{title:"Annuler une réalisation",subtitle:"Une contre-écriture commerciale exige autorité, motif et référence financière.",endpoint:"/api/revenue-command-center/contract/commands"},
  "add-risk":{title:"Déclarer un risque contractuel",subtitle:"Mesurez valeur exposée, sévérité, probabilité et mitigation.",endpoint:"/api/revenue-command-center/contract/risks"},
  "resolve-risk":{title:"Résoudre un risque",subtitle:"Conservez la preuve, la résolution et le risque résiduel.",endpoint:"/api/revenue-command-center/contract/commands"},
  "renewal-readiness":{title:"Préparer le renouvellement",subtitle:"Figez échéance, préavis, obligations ouvertes et prochaine décision.",endpoint:"/api/revenue-command-center/contract/commands"},
  "terminate-contract":{title:"Terminer le contrat",subtitle:"Cette décision exige motif, autorité, effet et preuve de communication.",endpoint:"/api/revenue-command-center/contract/commands"},
  "close-contract":{title:"Clôturer le contrat",subtitle:"Vérifiez obligations, paiement, handoff, archivage et audit avant clôture.",endpoint:"/api/revenue-command-center/contract/commands"},
  "evidence-viewer":{title:"Preuves contractuelles",subtitle:"Consultez les preuves liées aux signatures, conditions, paiements et activation.",endpoint:"",mode:"view"},
  "signature-history":{title:"Historique des signatures",subtitle:"Consultez demandes, rappels, preuves, vérifications et refus.",endpoint:"",mode:"view"},
  "payment-history":{title:"Historique financier commercial",subtitle:"Consultez exigences, promesses, handoffs, confirmations et écarts.",endpoint:"",mode:"view"},
  "activation-audit":{title:"Audit d’activation",subtitle:"Consultez chaque gate, décision, override et handoff.",endpoint:"",mode:"view"},
  "contract-audit":{title:"Audit contractuel",subtitle:"Consultez versions, transitions, décisions, preuves et événements immuables.",endpoint:"",mode:"view"},
}

export default function RevenueContractWorkspace({experience,contextId,contextType="partnership"}:Props){
  const contract=CONTRACT_ROUTE_CONTRACTS[experience]
  const {data,loading,error,refresh}=useContractPortfolio(experience,contextId,contextType)
  const [query,setQuery]=useState("")
  const [status,setStatus]=useState("all")
  const [selectedId,setSelectedId]=useState<string|null>(null)
  const [modal,setModal]=useState<ContractModalKind|null>(null)
  const [busy,setBusy]=useState(false)
  const [mutationError,setMutationError]=useState<string|null>(null)
  const [section,setSection]=useState("summary")

  const contracts=useMemo(()=>data.contracts.filter(item=>{
    const q=query.trim().toLowerCase();const match=!q||[item.title,item.reference,item.entity_name,item.account_name,item.opportunity_title,item.owner].some(v=>String(v||"").toLowerCase().includes(q));return match&&(status==="all"||item.status===status)
  }),[data.contracts,query,status])
  useEffect(()=>{if(!selectedId&&contracts[0])setSelectedId(contracts[0].id)},[contracts,selectedId])
  const selected=contracts.find(item=>item.id===selectedId)||data.contracts.find(item=>item.id===selectedId)||contracts[0]||null
  const related=(rows:Array<Record<string,any>>,key="contract_id")=>selected?rows.filter(row=>row[key]===selected.id||row.contract_id===selected.id):[]
  const versionRows=related(data.versions),reviewRows=related(data.reviews),approvalRows=related(data.approvals),signatoryRows=related(data.signatories),signatureRows=related(data.signatureEvents),conditionRows=related(data.conditions),obligationRows=related(data.obligations),milestoneRows=related(data.milestones),scheduleRows=related(data.paymentSchedules),requirementRows=related(data.paymentRequirements),promiseRows=related(data.paymentPromises),financeRows=related(data.financeHandoffs),confirmationRows=related(data.paymentConfirmations),gateRows=related(data.activationGates),decisionRows=related(data.activationDecisions),handoffRows=related(data.operationalHandoffs),realizationRows=related(data.realizationEvents),riskRows=related(data.risks),historyRows=related(data.statusHistory)

  function open(kind:ContractModalKind,record?:ContractRecord|null){if(record)setSelectedId(record.id);setMutationError(null);setModal(kind)}
  async function submit(kind:ContractModalKind,form:HTMLFormElement){
    const meta=MODAL_META[kind];if(!meta.endpoint)return setModal(null)
    const raw=Object.fromEntries(new FormData(form).entries());const body:any={...raw,contractId:selected?.id||raw.contractId||null,contextId,contextType,version:selected?.version||1}
    for(const [key,value] of Object.entries(body))if(typeof value==="string"&&/Value|Amount|Percent|Order|Priority|Days|value|amount|percent|order|days/.test(key))body[key]=value===""?0:Number(value)
    const commandKinds=["add-section","add-clause","commercial-term","review-decision","request-approval","approval-decision","signature-decline","signature-reminder","verify-condition","payment-requirement","promise-broken","finance-decision","payment-discrepancy","activation-override","handoff-acceptance","service-activation","suspend-activation","reverse-realization","resolve-risk","renewal-readiness","terminate-contract","close-contract"]
    if(commandKinds.includes(kind))body.command=kind
    setBusy(true);setMutationError(null)
    try{await contractMutation(meta.endpoint,body);setModal(null);await refresh(true)}catch(reason){setMutationError(reason instanceof Error?reason.message:String(reason))}finally{setBusy(false)}
  }

  if(loading)return <main className={styles.shell}><LoadingState/></main>
  if(error)return <main className={styles.shell}><ErrorState message={error} onRetry={()=>refresh()}/></main>

  return <main className={styles.shell} data-accent={contract.accent}>
    <header className={styles.hero}>
      <div className={styles.heroGlow}/>
      <nav className={styles.breadcrumbs} aria-label="Fil d’Ariane"><Link href="/revenue-command-center">Revenue Command</Link><ChevronRight size={13}/><span>{contract.title}</span></nav>
      <div className={styles.heroGrid}>
        <div><p className={styles.eyebrow}><span/> {contract.eyebrow}</p><h1>{contract.title}</h1><p className={styles.heroCopy}>{contract.mission}</p><p className={styles.trustLine}><ShieldCheck size={13}/> Traçabilité persistée · autorités vérifiées · preuves obligatoires</p><div className={styles.heroActions}><button className={styles.primaryButton} onClick={()=>open(experience.includes("activation")||experience==="system-activation"?"evaluate-activation":"create-contract",selected)}><Plus size={16}/>{contract.primaryAction}</button><button className={styles.secondaryButton} onClick={()=>refresh()}><RefreshCw size={15}/>Actualiser</button></div></div>
        <div className={styles.authorityCard}><div className={styles.authorityIcon}><ShieldCheck size={24}/></div><div><span>DOCTRINE D’AUTORITÉ</span><strong>Aucune activation par hypothèse</strong><p>Version, approbation, signature, preuve Finance, gates et handoff restent vérifiables avant chaque décision.</p></div></div>
      </div>
      <div className={styles.commandStrip}>{CONTRACT_NAVIGATION.map(([name,href])=><Link key={href} href={href} className={styles.commandLink}>{name}<ArrowRight size={13}/></Link>)}</div>
    </header>

    <section className={styles.kpiGrid}>
      <Kpi icon={<FileSignature/>} label="Contrats" value={String(data.summary.total)} hint={`${data.summary.preparation} en préparation`} tone="blue"/>
      <Kpi icon={<CircleDollarSign/>} label="Valeur contractée" value={dh(data.summary.contractValueMad)} hint={`${data.summary.signaturePending} signatures en attente`} tone="navy"/>
      <Kpi icon={<WalletCards/>} label="Paiements confirmés" value={dh(data.summary.paymentConfirmedMad)} hint={`${dh(data.summary.paymentPendingMad)} encore attendus`} tone="green"/>
      <Kpi icon={<Zap/>} label="Prêts à activer" value={String(data.summary.activationReady)} hint={`${data.summary.paymentBlocked} bloqués par paiement`} tone="amber"/>
      <Kpi icon={<TrendingUp/>} label="Revenu réalisé" value={dh(data.summary.realizedMad)} hint={`${dh(data.summary.realizableMad)} éligibles`} tone="violet"/>
      <Kpi icon={<ShieldAlert/>} label="Exposition" value={String(data.summary.atRisk)} hint={`${data.summary.overdueObligations} obligations en retard`} tone="red"/>
    </section>

    {experience==="contract-command"&&<CommandExperience contracts={contracts} data={data} selected={selected} onSelect={setSelectedId} open={open}/>}
    {experience==="contract-portfolio"&&<PortfolioExperience contracts={contracts} selected={selected} onSelect={setSelectedId} query={query} setQuery={setQuery} status={status} setStatus={setStatus} open={open}/>}
    {experience==="contract-studio"&&<StudioExperience contract={selected} section={section} setSection={setSection} versions={versionRows} reviews={reviewRows} approvals={approvalRows} signatories={signatoryRows} conditions={conditionRows} obligations={obligationRows} milestones={milestoneRows} open={open}/>}
    {experience==="activation-command"&&<ActivationCommand contracts={contracts} gates={data.activationGates} promises={data.paymentPromises} finance={data.financeHandoffs} realizations={data.realizationEvents} open={open} onSelect={setSelectedId}/>}
    {experience==="activation-dossier"&&<ActivationDossier contract={selected} requirements={requirementRows} schedules={scheduleRows} promises={promiseRows} finance={financeRows} confirmations={confirmationRows} gates={gateRows} decisions={decisionRows} handoffs={handoffRows} realizations={realizationRows} risks={riskRows} open={open}/>}
    {experience==="system-activation"&&<SystemAuthority contracts={contracts} data={data} open={open} onSelect={setSelectedId}/>}

    {selected&&experience!=="contract-studio"&&experience!=="activation-dossier"&&<section className={styles.bottomGrid}>
      <Panel title="Dossier actuellement sélectionné" subtitle="Accédez aux preuves et décisions exactes" icon={<FileLock2 size={17}/>}><ContractMiniDossier contract={selected} open={open}/></Panel>
      <Panel title="Historique & audit" subtitle="Transitions immuables et responsabilités" icon={<History size={17}/>}><Timeline rows={[...historyRows,...signatureRows,...realizationRows].slice(0,8)}/></Panel>
    </section>}

    {modal&&<EnterpriseModal kind={modal} contract={selected} data={data} busy={busy} error={mutationError} close={()=>setModal(null)} submit={submit}/>}
  </main>
}

function CommandExperience({contracts,data,selected,onSelect,open}:any){
  const priority=contracts.filter((c:ContractRecord)=>["approval_required","signature_pending","partially_signed","conditions_pending","activation_pending","suspended"].includes(c.status)||["blocked","overdue","broken"].includes(String(c.payment_gate_status))).slice(0,10)
  return <>
    <section className={styles.commandLayout}>
      <Panel title="File d’intervention exécutive" subtitle="Contrats dont la valeur dépend d’une décision immédiate" icon={<AlertOctagon size={17}/>} className={styles.span2}>
        <div className={styles.priorityList}>{priority.map((item:ContractRecord)=><button key={item.id} className={`${styles.priorityRow} ${selected?.id===item.id?styles.selectedRow:""}`} onClick={()=>onSelect(item.id)}><span className={`${styles.statusDot} ${tone(item.status)}`}/><div><strong>{item.title}</strong><p>{item.entity_name||item.account_name||"Compte relié"} · {label(item.status)} · {item.owner||"Non attribué"}</p></div><b>{dh(item.contract_value)}</b></button>)}{!priority.length&&<Empty title="Aucune intervention critique" text="Les contrats en attente d’autorité apparaîtront ici."/>}</div>
      </Panel>
      <Panel title="Matrice des gates" subtitle="Signature, effectivité, paiement, activation" icon={<ClipboardCheck size={17}/>}><GateSummary data={data}/></Panel>
      <Panel title="Revenu empêché" subtitle="Valeur bloquée avant réalisation" icon={<LockKeyhole size={17}/>}><div className={styles.bigMetric}>{dh(Math.max(0,data.summary.contractValueMad-data.summary.realizedMad))}</div><p className={styles.muted}>La valeur reste contractée mais non réalisée tant que les conditions autoritatives ne sont pas remplies.</p><button className={styles.inlineButton} onClick={()=>selected&&open("evaluate-activation",selected)}>Évaluer les gates <ArrowRight size={14}/></button></Panel>
    </section>
    <section className={styles.bottomGrid}><Panel title="Signatures & conditions" subtitle="Pression de closing" icon={<FileSignature size={17}/>}><MiniBars items={[['Signatures en attente',data.summary.signaturePending],['Contrats signés',data.summary.fullySigned],['Conditions ouvertes',data.summary.conditionsPending],['Échéances proches',data.summary.expiring]]}/></Panel><Panel title="Paiement & réalisation" subtitle="Vérité financière commerciale" icon={<Landmark size={17}/>}><ValueStack items={[['Attendu',data.summary.paymentPendingMad],['Confirmé',data.summary.paymentConfirmedMad],['Réalisable',data.summary.realizableMad],['Réalisé',data.summary.realizedMad]]}/></Panel></section>
  </>
}

function PortfolioExperience({contracts,selected,onSelect,query,setQuery,status,setStatus,open}:any){return <section className={styles.registry}>
  <div className={styles.registryToolbar}><div className={styles.searchBox}><Search size={15}/><input value={query} onChange={(e:any)=>setQuery(e.target.value)} placeholder="Rechercher contrat, compte, opportunité, propriétaire…"/></div><select value={status} onChange={(e:any)=>setStatus(e.target.value)}><option value="all">Tous les statuts</option>{["draft","internal_review","approval_required","approved","signature_pending","partially_signed","fully_signed","conditions_pending","effective","activation_pending","active","suspended","completed","expired","terminated"].map(item=><option key={item} value={item}>{label(item)}</option>)}</select><button className={styles.primaryButton} onClick={()=>open("create-contract",selected)}><Plus size={15}/>Nouveau contrat</button></div>
  <div className={styles.registryGrid}><div className={styles.tableWrap}><table><thead><tr><th>Contrat</th><th>Compte</th><th>Valeur</th><th>Signature</th><th>Paiement</th><th>Activation</th><th>Échéance</th><th/></tr></thead><tbody>{contracts.map((item:ContractRecord)=><tr key={item.id} className={selected?.id===item.id?styles.activeTableRow:""} onClick={()=>onSelect(item.id)}><td><strong>{item.reference||"Contrat"}</strong><span>{item.title}</span></td><td>{item.entity_name||item.account_name||"—"}</td><td><b>{dh(item.contract_value)}</b></td><td><Status value={item.signature_status}/></td><td><Status value={item.payment_gate_status}/></td><td><Status value={item.activation_status}/></td><td>{date(item.expiry_date)}</td><td><ChevronRight size={15}/></td></tr>)}</tbody></table>{!contracts.length&&<Empty title="Aucun contrat correspondant" text="Ajustez les filtres ou créez un contrat depuis un handoff commercial accepté."/>}</div><aside className={styles.sideDossier}>{selected?<ContractMiniDossier contract={selected} open={open}/>:<Empty title="Sélectionnez un contrat" text="Le dossier contextuel apparaîtra ici."/>}</aside></div>
</section>}

function StudioExperience({contract,section,setSection,versions,reviews,approvals,signatories,conditions,obligations,milestones,open}:any){if(!contract)return <Empty title="Aucun contrat disponible" text="Créez un contrat depuis une position commerciale acceptée."/>;const sections=[['summary','Synthèse'],['clauses','Clauses'],['obligations','Obligations'],['signature','Signatures'],['conditions','Effectivité'],['finance','Paiement'],['versions','Versions'],['audit','Audit']];return <section className={styles.studio}>
  <aside className={styles.studioNav}><div className={styles.studioIdentity}><FileSignature size={23}/><span>CONTRACT STUDIO</span><strong>{contract.reference}</strong><p>{contract.entity_name||contract.account_name||contract.title}</p></div>{sections.map(([key,name])=><button key={key} onClick={()=>setSection(key)} className={section===key?styles.activeNav:""}>{name}<ChevronRight size={13}/></button>)}<div className={styles.studioNavActions}><button onClick={()=>open("create-version",contract)}><Layers3 size={14}/>Figer une version</button><button onClick={()=>open("request-review",contract)}><Scale size={14}/>Soumettre en revue</button></div></aside>
  <div className={styles.studioCanvas}><div className={styles.studioTop}><div><p>{label(contract.status)}</p><h2>{contract.title}</h2><span>{dh(contract.contract_value)} · {contract.owner}</span></div><div className={styles.studioTopActions}><button onClick={()=>open("compare-versions",contract)}>Comparer</button><button className={styles.primaryButton} onClick={()=>open("add-clause",contract)}><Plus size={14}/>Clause</button></div></div>
    {section==="summary"&&<div className={styles.canvasGrid}><Panel title="Source commerciale" subtitle="Version acceptée et valeur autoritative" icon={<Handshake size={17}/>}><DefinitionList items={[['Proposition',contract.proposal_id||'—'],['Version acceptée',contract.proposal_version_id||'—'],['Opportunité',contract.opportunity_title||contract.opportunity_id||'—'],['Valeur',dh(contract.contract_value)],['Effectivité',label(contract.effectiveness_status)],['Prochaine action',contract.next_action||'—']]}/></Panel><Panel title="Contrôle de complétude" subtitle="Conditions avant signature" icon={<BadgeCheck size={17}/>}><GateCards rows={[['Revue',contract.review_status],['Approbation',contract.approval_status],['Signature',contract.signature_status],['Paiement',contract.payment_gate_status]]}/></Panel></div>}
    {section==="clauses"&&<StudioSection title="Architecture contractuelle" description="Séparez portée, conditions commerciales, clauses client et notes internes." actions={<><button onClick={()=>open('add-section',contract)}>Ajouter section</button><button onClick={()=>open('add-clause',contract)}>Ajouter clause</button><button onClick={()=>open('commercial-term',contract)}>Condition commerciale</button></>}><ContractDocument contract={contract}/></StudioSection>}
    {section==="obligations"&&<StudioSection title="Obligations & jalons" description="Chaque engagement doit être possédé, daté, prouvé et relié à son effet."><div className={styles.twoColumns}><RecordList rows={obligations} empty="Aucune obligation" fields={['description','responsible_party','due_at','status']}/><RecordList rows={milestones} empty="Aucun jalon" fields={['title','due_at','status','payment_dependency']}/></div><div className={styles.actionRow}><button onClick={()=>open('add-obligation',contract)}>Nouvelle obligation</button><button onClick={()=>open('add-milestone',contract)}>Nouveau jalon</button></div></StudioSection>}
    {section==="signature"&&<StudioSection title="Structure de signature" description="Ordre, rôle, demande, preuve et vérification restent distincts."><SignatoryMatrix rows={signatories}/><div className={styles.actionRow}><button onClick={()=>open('add-signatory',contract)}>Ajouter signataire</button><button onClick={()=>open('signature-request',contract)}>Demander signature</button><button onClick={()=>open('signature-evidence',contract)}>Enregistrer preuve</button></div></StudioSection>}
    {section==="conditions"&&<StudioSection title="Conditions d’effectivité" description="Le contrat signé reste bloqué tant que les conditions obligatoires ne sont pas vérifiées."><RecordList rows={conditions} empty="Aucune condition préalable" fields={['title','owner','required','status']}/><div className={styles.actionRow}><button onClick={()=>open('add-condition',contract)}>Ajouter condition</button><button onClick={()=>open('verify-condition',contract)}>Vérifier preuve</button><button onClick={()=>open('evaluate-effectiveness',contract)}>Évaluer effectivité</button></div></StudioSection>}
    {section==="finance"&&<StudioSection title="Conditions financières" description="Revenue prépare les exigences; Finance reste la source de vérité du paiement."><div className={styles.financeBanner}><Landmark size={22}/><div><strong>{dh(contract.contract_value)}</strong><span>Valeur contractuelle</span></div><div><strong>{label(contract.payment_gate_status)}</strong><span>Gate paiement</span></div><div><strong>{dh(contract.realized_value)}</strong><span>Revenu réalisé</span></div></div><div className={styles.actionRow}><button onClick={()=>open('payment-terms',contract)}>Conditions paiement</button><button onClick={()=>open('finance-handoff',contract)}>Handoff Finance</button><button onClick={()=>open('payment-confirmation',contract)}>Confirmation</button></div></StudioSection>}
    {section==="versions"&&<StudioSection title="Versions immuables" description="Une version approuvée ou signée ne peut jamais être modifiée silencieusement."><RecordList rows={versions} empty="Aucune version figée" fields={['version_number','revision_reason','approval_status','created_at']}/><div className={styles.actionRow}><button onClick={()=>open('create-version',contract)}>Créer version</button><button onClick={()=>open('compare-versions',contract)}>Comparer</button></div></StudioSection>}
    {section==="audit"&&<StudioSection title="Revue, approbation & audit" description="Chaque décision conserve son auteur, son motif et sa conséquence."><div className={styles.twoColumns}><RecordList rows={reviews} empty="Aucune revue" fields={['review_type','status','decision','created_at']}/><RecordList rows={approvals} empty="Aucune approbation" fields={['approval_type','status','reason','created_at']}/></div><div className={styles.actionRow}><button onClick={()=>open('contract-audit',contract)}>Ouvrir audit</button><button onClick={()=>open('evidence-viewer',contract)}>Voir preuves</button></div></StudioSection>}
  </div>
</section>}

function ActivationCommand({contracts,gates,promises,finance,realizations,open,onSelect}:any){const blocked=contracts.filter((c:ContractRecord)=>!["ready","authorized","active"].includes(String(c.activation_status))||["blocked","overdue","broken"].includes(String(c.payment_gate_status)));return <section className={styles.activationCommand}>
  <div className={styles.activationHero}><div><span>ACTIVATION CONTROL</span><h2>Aucune mise en service sans autorité contractuelle et financière</h2><p>Chaque ligne expose les gates passés, ouverts, échoués et l’effet exact sur le revenu.</p></div><ShieldAlert size={52}/></div>
  <div className={styles.gateBoard}>{contracts.map((item:ContractRecord)=>{const itemGates=gates.filter((g:any)=>g.contract_id===item.id);const passed=itemGates.filter((g:any)=>g.status==="passed").length;return <button key={item.id} className={styles.gateContract} onClick={()=>onSelect(item.id)}><div className={styles.gateContractTop}><span className={`${styles.statusDot} ${tone(item.activation_status)}`}/><strong>{item.title}</strong><b>{dh(item.contract_value)}</b></div><p>{item.entity_name||item.account_name||"Compte relié"}</p><div className={styles.gateProgress}><span style={{width:`${itemGates.length?Math.round(passed/itemGates.length*100):0}%`}}/></div><div className={styles.gateFooter}><span>{passed}/{itemGates.length||0} gates</span><Status value={item.payment_gate_status}/></div></button>})}{!contracts.length&&<Empty title="Aucun contrat à activer" text="Les contrats effectifs apparaîtront après signature et vérification des conditions."/>}</div>
  <div className={styles.bottomGrid}><Panel title="Promesses & pression de paiement" subtitle="Une promesse n’est pas une confirmation" icon={<CalendarClock size={17}/>}><RecordList rows={promises.slice(0,8)} empty="Aucune promesse active" fields={['expected_amount','promised_date','status','customer_contact']}/></Panel><Panel title="Handoffs Finance" subtitle="Soumission et acceptation inter-départementale" icon={<Landmark size={17}/>}><RecordList rows={finance.slice(0,8)} empty="Aucun handoff" fields={['status','final_value','finance_reference','created_at']}/></Panel><Panel title="Réalisation" subtitle="Valeur confirmée et reproductible" icon={<TrendingUp size={17}/>}><RecordList rows={realizations.slice(0,8)} empty="Aucune réalisation" fields={['amount','status','finance_reference','realized_at']}/></Panel></div>
  {blocked[0]&&<div className={styles.floatingAction}><div><strong>{blocked.length} dossier(s) exigent une décision</strong><span>Évaluez les gates avant tout engagement opérationnel.</span></div><button onClick={()=>open('evaluate-activation',blocked[0])}>Évaluer maintenant <ArrowRight size={14}/></button></div>}
</section>}

function ActivationDossier({contract,requirements,schedules,promises,finance,confirmations,gates,decisions,handoffs,realizations,risks,open}:any){if(!contract)return <Empty title="Aucun dossier d’activation" text="Sélectionnez un accord actif ou prêt à être évalué."/>;return <section className={styles.activationDossier}>
  <div className={styles.activationHeader}><div><p>ACTIVATION DOSSIER</p><h2>{contract.title}</h2><span>{contract.entity_name||contract.account_name||"Compte relié"} · {dh(contract.contract_value)}</span></div><div className={styles.activationScore}><strong>{gateScore(contract,gates)}%</strong><span>préparation gates</span></div></div>
  <div className={styles.activationColumns}>
    <Panel title="Paiement contractuel" subtitle="Exigences, échéances, promesses et confirmation" icon={<WalletCards size={17}/>}><GateRecords title="Exigences" rows={requirements}/><GateRecords title="Échéances" rows={schedules}/><GateRecords title="Promesses" rows={promises}/><GateRecords title="Confirmations" rows={confirmations}/><div className={styles.actionRow}><button onClick={()=>open('payment-schedule',contract)}>Échéance</button><button onClick={()=>open('payment-promise',contract)}>Promesse</button><button onClick={()=>open('payment-confirmation',contract)}>Confirmation</button></div></Panel>
    <Panel title="Gates & autorité" subtitle="Résultats calculés, décision et éventuelle dérogation" icon={<ShieldCheck size={17}/>}><GateCards rows={gates.map((g:any)=>[g.gate_key||g.title,g.status])}/><RecordList rows={decisions} empty="Aucune décision d’activation" fields={['decision','reason','decided_at']}/><div className={styles.actionRow}><button onClick={()=>open('evaluate-activation',contract)}>Évaluer</button><button onClick={()=>open('activation-decision',contract)}>Décider</button><button onClick={()=>open('activation-override',contract)}>Dérogation</button></div></Panel>
    <Panel title="Handoff opérationnel" subtitle="Acceptation par le module receveur" icon={<BriefcaseBusiness size={17}/>}><RecordList rows={handoffs} empty="Aucun handoff opérationnel" fields={['receiving_module','receiving_owner','status','start_date']}/><div className={styles.actionRow}><button onClick={()=>open('operational-handoff',contract)}>Créer handoff</button><button onClick={()=>open('handoff-acceptance',contract)}>Accepter</button><button onClick={()=>open('service-activation',contract)}>Activer</button></div></Panel>
  </div>
  <div className={styles.bottomGrid}><Panel title="Finance handoff" subtitle="Références autoritatives sans doublon comptable" icon={<Landmark size={17}/>}><RecordList rows={finance} empty="Aucun handoff Finance" fields={['status','final_value','finance_reference','created_at']}/></Panel><Panel title="Réalisation du revenu" subtitle="Événements confirmés et réversibles sous autorité" icon={<CircleDollarSign size={17}/>}><RecordList rows={realizations} empty="Aucun revenu réalisé" fields={['amount','status','finance_reference','realized_at']}/><button className={styles.inlineButton} onClick={()=>open('realization',contract)}>Confirmer réalisation <ArrowRight size={14}/></button></Panel><Panel title="Risques" subtitle="Contrat, paiement, activation et obligation" icon={<AlertTriangle size={17}/>}><RecordList rows={risks} empty="Aucun risque ouvert" fields={['risk_type','severity','status','mitigation']}/><button className={styles.inlineButton} onClick={()=>open('add-risk',contract)}>Déclarer un risque <ArrowRight size={14}/></button></Panel></div>
</section>}

function SystemAuthority({contracts,data,open,onSelect}:any){const critical=contracts.filter((c:ContractRecord)=>c.activation_status!=="active"&&Number(c.contract_value||0)>0).sort((a:ContractRecord,b:ContractRecord)=>Number(b.contract_value||0)-Number(a.contract_value||0));return <section className={styles.systemAuthority}>
  <div className={styles.systemBanner}><div className={styles.systemSeal}><ShieldAlert size={36}/></div><div><span>AUTORITÉ CENTRALE</span><h2>Activation, dérogation et revenu réalisé sous contrôle exécutif</h2><p>Les données contractuelles et financières restent séparées; les décisions critiques exigent une preuve et une autorité identifiable.</p></div><div className={styles.systemValue}><strong>{dh(critical.reduce((s:number,c:ContractRecord)=>s+Number(c.contract_value||0),0))}</strong><span>valeur non activée</span></div></div>
  <div className={styles.authorityMatrix}><div className={styles.matrixHead}><span>Dossier</span><span>Contrat</span><span>Signature</span><span>Paiement</span><span>Activation</span><span>Valeur</span><span>Décision</span></div>{critical.map((item:ContractRecord)=><div key={item.id} className={styles.matrixRow}><button onClick={()=>onSelect(item.id)}>{item.entity_name||item.account_name||item.title}</button><Status value={item.status}/><Status value={item.signature_status}/><Status value={item.payment_gate_status}/><Status value={item.activation_status}/><b>{dh(item.contract_value)}</b><button className={styles.matrixAction} onClick={()=>{onSelect(item.id);open('evaluate-activation',item)}}>Évaluer</button></div>)}{!critical.length&&<Empty title="Aucune activation critique" text="Tous les dossiers visibles satisfont actuellement leur état d’autorité."/>}</div>
  <div className={styles.executiveMetrics}><ExecutiveMetric icon={<FileCheck2/>} value={String(data.summary.fullySigned)} label="Contrats pleinement signés"/><ExecutiveMetric icon={<Landmark/>} value={dh(data.summary.paymentConfirmedMad)} label="Paiements confirmés"/><ExecutiveMetric icon={<Zap/>} value={String(data.summary.activationReady)} label="Dossiers prêts"/><ExecutiveMetric icon={<TrendingUp/>} value={dh(data.summary.realizedMad)} label="Revenu réalisé"/><ExecutiveMetric icon={<AlertOctagon/>} value={String(data.summary.atRisk)} label="Risques ouverts"/></div>
</section>}

function EnterpriseModal({kind,contract,data,busy,error,close,submit}:{kind:ContractModalKind;contract:any;data:any;busy:boolean;error:string|null;close:()=>void;submit:(kind:ContractModalKind,form:HTMLFormElement)=>void}){const meta=MODAL_META[kind];const box=useRef<HTMLDivElement|null>(null);useEffect(()=>{const prior=document.activeElement as HTMLElement|null;const key=(event:KeyboardEvent)=>{if(event.key==="Escape"&&!busy)close();if(event.key==="Tab"&&box.current){const focus=[...box.current.querySelectorAll<HTMLElement>('button,input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(el=>!el.hasAttribute('disabled'));if(!focus.length)return;const first=focus[0],last=focus[focus.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}};document.addEventListener("keydown",key);document.body.style.overflow="hidden";setTimeout(()=>box.current?.querySelector<HTMLElement>('input,select,textarea,button')?.focus(),0);return()=>{document.removeEventListener("keydown",key);document.body.style.overflow="";prior?.focus()}},[busy,close]);return <div className={styles.modalBackdrop} role="presentation" onMouseDown={(e:any)=>{if(e.target===e.currentTarget&&!busy)close()}}><div className={styles.modal} ref={box} role="dialog" aria-modal="true" aria-labelledby="contract-modal-title"><div className={styles.modalHeader}><div><p>ANGELCARE CONTRACT CONTROL</p><h2 id="contract-modal-title">{meta.title}</h2><span>{meta.subtitle}</span></div><button onClick={close} disabled={busy} aria-label="Fermer"><X size={18}/></button></div>{meta.mode==="view"?<Viewer kind={kind} contract={contract} data={data}/>:<form onSubmit={(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();void submit(kind,e.currentTarget)}}><div className={styles.modalBody}><ContractForm kind={kind} contract={contract} data={data}/>{error&&<div className={styles.modalError}><AlertTriangle size={16}/>{error}</div>}</div><div className={styles.modalFooter}><button type="button" onClick={close} disabled={busy}>Annuler</button><button className={styles.primaryButton} type="submit" disabled={busy}>{busy?"Exécution contrôlée…":"Confirmer l’opération"}</button></div></form>}</div></div>}

function ContractForm({kind,contract,data}:any){
  if(kind==="create-contract")return <FormGrid><RecordSelect name="contractHandoffId" label="Handoff commercial accepté" records={data.handoffs.filter((r:any)=>r.status!=="consumed")} labelKeys={["proposal_id","final_value"]}/><Input name="title" label="Titre du contrat" defaultValue={contract?.title||"Contrat commercial ANGELCARE"} required/><Input name="owner" label="Propriétaire" defaultValue={contract?.owner||"Revenue Manager"}/><Input name="contractValue" label="Valeur contractuelle Dh" type="number" defaultValue={String(contract?.contract_value||0)} required/><Input name="effectiveDate" label="Date d’effet cible" type="date"/><Input name="expiryDate" label="Date d’expiration" type="date"/><Textarea name="nextAction" label="Prochaine action" wide/></FormGrid>
  if(["add-section","add-clause","commercial-term"].includes(kind))return <FormGrid><Input name="title" label={kind==="add-section"?"Titre de section":kind==="add-clause"?"Titre de clause":"Nom de la condition"} required/><Select name="visibility" label="Visibilité" options={["customer","internal","restricted"]}/><Textarea name="customerContent" label="Contenu client" wide required/><Textarea name="internalContent" label="Notes internes" wide/><Input name="sortOrder" label="Ordre" type="number"/></FormGrid>
  if(kind==="add-obligation")return <FormGrid><Select name="responsibleParty" label="Partie responsable" options={["angelcare","customer","shared"]}/><Input name="owner" label="Responsable opérationnel"/><Input name="dueAt" label="Échéance" type="date"/><Select name="evidenceRequired" label="Preuve requise" options={["true","false"]}/><Textarea name="description" label="Obligation exacte" wide required/><Textarea name="acceptanceCriteria" label="Critères d’acceptation" wide/></FormGrid>
  if(kind==="add-milestone")return <FormGrid><Input name="title" label="Jalon" required/><Input name="dueAt" label="Échéance" type="date"/><Input name="owner" label="Responsable"/><Select name="paymentDependency" label="Dépendance paiement" options={["none","deposit","milestone","balance"]}/><Textarea name="deliverable" label="Livrable" wide/><Textarea name="acceptanceCriteria" label="Critères d’acceptation" wide/></FormGrid>
  if(kind==="create-version")return <FormGrid><Input name="revisionReason" label="Motif de version" required/><Textarea name="changes" label="Changements contractuels" wide required/><Textarea name="internalRationale" label="Rationale interne" wide/></FormGrid>
  if(kind==="request-review")return <FormGrid><Select name="reviewType" label="Type de revue" options={["commercial","finance","operations","legal","executive"]}/><Input name="reviewer" label="Relecteur / autorité"/><Input name="dueAt" label="Échéance" type="date"/><Textarea name="reason" label="Objet de la revue" wide required/><Textarea name="evidence" label="Pièces et contexte" wide/></FormGrid>
  if(["review-decision","request-approval","approval-decision"].includes(kind))return <FormGrid><Select name="decision" label="Décision" options={kind==="request-approval"?["requested"]:["approved","rejected","correction_required"]}/><Textarea name="reason" label="Motif et réserves" wide required/><Textarea name="evidence" label="Référence de preuve" wide/></FormGrid>
  if(kind==="add-signatory")return <FormGrid><Select name="partyType" label="Partie" options={["angelcare","customer","partner"]}/><Input name="name" label="Nom complet" required/><Input name="email" label="Email" type="email"/><Input name="role" label="Qualité / rôle" required/><Input name="signingOrder" label="Ordre de signature" type="number" defaultValue="1"/><Select name="required" label="Obligatoire" options={["true","false"]}/></FormGrid>
  if(["signature-request","signature-evidence","signature-decline","signature-reminder"].includes(kind))return <FormGrid><RecordSelect name="signatoryId" label="Signataire" records={data.signatories.filter((r:any)=>!contract||r.contract_id===contract.id)} labelKeys={["name","role"]}/><Select name="eventType" label="Événement" options={kind==="signature-request"?["requested"]:kind==="signature-evidence"?["signed","verified"]:kind==="signature-decline"?["declined"]:["reminder_sent"]}/><Input name="dueAt" label="Échéance / date" type="date"/><Input name="evidenceReference" label="Référence de preuve"/><Textarea name="reason" label="Détail, canal ou motif" wide required/></FormGrid>
  if(kind==="add-condition")return <FormGrid><Input name="title" label="Condition préalable" required/><Select name="conditionType" label="Type" options={["signature","approval","payment","document","customer_prerequisite","angelcare_prerequisite","compliance","date"]}/><Input name="owner" label="Responsable"/><Input name="dueAt" label="Échéance" type="date"/><Select name="required" label="Obligatoire" options={["true","false"]}/><Textarea name="description" label="Condition exacte" wide/><Textarea name="evidenceRequirements" label="Preuve attendue" wide/></FormGrid>
  if(kind==="verify-condition")return <FormGrid><RecordSelect name="conditionId" label="Condition" records={data.conditions.filter((r:any)=>!contract||r.contract_id===contract.id)} labelKeys={["title","status"]}/><Select name="decision" label="Décision" options={["verified","rejected","pending"]}/><Input name="evidenceReference" label="Référence de preuve" required/><Textarea name="reason" label="Motif" wide required/></FormGrid>
  if(kind==="payment-terms")return <FormGrid><Select name="termType" label="Structure" options={["deposit","one_time","recurring","milestone","monthly","quarterly","balance"]}/><Input name="depositAmount" label="Dépôt Dh" type="number"/><Input name="depositPercent" label="Dépôt %" type="number"/><Input name="paymentDays" label="Délai de paiement (jours)" type="number"/><Select name="activationDependency" label="Impact activation" options={["mandatory","advisory","none"]}/><Textarea name="terms" label="Conditions exactes" wide required/></FormGrid>
  if(kind==="payment-schedule")return <FormGrid><Select name="scheduleType" label="Type d’échéance" options={["deposit","milestone","monthly","quarterly","balance","one_time"]}/><Input name="amount" label="Montant Dh" type="number" required/><Input name="dueDate" label="Date d’échéance" type="date" required/><Input name="trigger" label="Déclencheur"/><Select name="activationBlocking" label="Bloque l’activation" options={["true","false"]}/><Textarea name="notes" label="Notes" wide/></FormGrid>
  if(kind==="payment-promise")return <FormGrid><Input name="expectedAmount" label="Montant promis Dh" type="number" required/><Input name="promisedDate" label="Date promise" type="date" required/><Input name="customerContact" label="Contact client"/><Select name="confidence" label="Confiance" options={["low","medium","high","confirmed"]}/><Input name="sourceReference" label="Communication source"/><Textarea name="reason" label="Contexte" wide required/></FormGrid>
  if(kind==="collection-action")return <FormGrid><Select name="channel" label="Canal" options={["email","whatsapp","phone","meeting","internal"]}/><Input name="owner" label="Responsable"/><Input name="dueAt" label="Échéance" type="date"/><Select name="escalationLevel" label="Escalade" options={["none","manager","executive","finance"]}/><Textarea name="action" label="Action de recouvrement" wide required/><Textarea name="outcome" label="Résultat éventuel" wide/></FormGrid>
  if(kind==="finance-handoff")return <FormGrid><Input name="billingIdentity" label="Identité de facturation"/><Input name="finalValue" label="Valeur finale Dh" type="number" defaultValue={String(contract?.contract_value||0)} required/><Input name="depositRequired" label="Dépôt requis Dh" type="number"/><Input name="financeRecipient" label="Destinataire Finance"/><Input name="idempotencyKey" label="Clé d’idempotence" defaultValue={contract?`contract-${contract.id}`:""}/><Textarea name="paymentTerms" label="Conditions de paiement" wide required/><Textarea name="supportingDocuments" label="Pièces jointes / références" wide/></FormGrid>
  if(kind==="payment-confirmation")return <FormGrid><Input name="expectedAmount" label="Montant attendu Dh" type="number"/><Input name="confirmedAmount" label="Montant confirmé Dh" type="number" required/><Input name="paymentDate" label="Date de paiement" type="date" required/><Input name="financeReference" label="Référence Finance" required/><Input name="receiptReference" label="Référence reçu"/><Input name="evidenceReference" label="Preuve vérifiée" required/><Textarea name="notes" label="Notes de rapprochement" wide/></FormGrid>
  if(["evaluate-effectiveness","evaluate-activation"].includes(kind))return <FormGrid><Textarea name="reason" label="Motif de réévaluation" wide required/><Select name="createTasks" label="Créer les tâches de blocage" options={["true","false"]}/></FormGrid>
  if(["activation-decision","activation-override"].includes(kind))return <FormGrid><Select name="decision" label="Décision" options={kind==="activation-decision"?["authorized","rejected"]:["override_requested","override_approved","override_rejected"]}/><Textarea name="reason" label="Justification et risque" wide required/><Input name="evidenceReference" label="Référence de preuve" required/></FormGrid>
  if(kind==="operational-handoff")return <FormGrid><Input name="receivingModule" label="Module receveur" required/><Input name="receivingOwner" label="Responsable receveur" required/><Input name="startDate" label="Date de démarrage" type="date"/><Textarea name="serviceScope" label="Portée du service" wide required/><Textarea name="commitments" label="Engagements commerciaux" wide/><Textarea name="risks" label="Risques et réserves" wide/></FormGrid>
  if(kind==="realization")return <FormGrid><Input name="amount" label="Montant à réaliser Dh" type="number" required/><Input name="financeReference" label="Référence Finance" required/><Input name="evidenceReference" label="Preuve autoritative" required/><Input name="realizedAt" label="Date de réalisation" type="date"/><Textarea name="rule" label="Règle de réalisation" wide required/></FormGrid>
  if(kind==="add-risk")return <FormGrid><Select name="riskType" label="Type de risque" options={["signature","approval","payment","obligation","activation","renewal","termination"]}/><Select name="severity" label="Sévérité" options={["low","medium","high","critical"]}/><Input name="probabilityPercent" label="Probabilité %" type="number"/><Input name="valueAtRisk" label="Valeur exposée Dh" type="number"/><Input name="owner" label="Responsable"/><Textarea name="description" label="Risque exact" wide required/><Textarea name="mitigation" label="Mitigation" wide/></FormGrid>
  if(kind==="renewal-readiness")return <FormGrid><Input name="renewalDecisionDate" label="Date de décision" type="date" required/><Input name="noticeDate" label="Date de préavis" type="date"/><Select name="renewalType" label="Type" options={["manual","automatic","renegotiation","new_proposal"]}/><Textarea name="requirements" label="Conditions de renouvellement" wide/><Textarea name="nextAction" label="Prochaine action" wide required/></FormGrid>
  if(["terminate-contract","close-contract","resolve-risk","promise-broken","payment-discrepancy","reverse-realization","suspend-activation","handoff-acceptance","service-activation","finance-decision"].includes(kind))return <FormGrid><Select name="decision" label="Décision" options={["confirmed","rejected","resolved","accepted","clarification_required","terminated","closed","suspended","activated","broken"]}/><Input name="reference" label="Référence / preuve"/><Textarea name="reason" label="Motif et conséquence" wide required/></FormGrid>
  return <FormGrid><Textarea name="reason" label="Motif de l’opération" wide required/></FormGrid>
}

function Viewer({kind,contract,data}:any){const rows=kind==="compare-versions"?data.versions.filter((r:any)=>r.contract_id===contract?.id):kind==="signature-history"?[...data.signatureEvents,...data.signatureEvidence].filter((r:any)=>r.contract_id===contract?.id):kind==="payment-history"?[...data.paymentSchedules,...data.paymentPromises,...data.financeHandoffs,...data.paymentConfirmations].filter((r:any)=>r.contract_id===contract?.id):kind==="activation-audit"?[...data.activationGates,...data.activationDecisions,...data.operationalHandoffs].filter((r:any)=>r.contract_id===contract?.id):kind==="evidence-viewer"?[...data.signatureEvidence,...data.conditionEvidence,...data.paymentConfirmations].filter((r:any)=>r.contract_id===contract?.id):[...data.statusHistory,...data.reviews,...data.approvals].filter((r:any)=>r.contract_id===contract?.id);return <div className={styles.modalBody}><div className={styles.viewerHeader}><FileLock2 size={20}/><div><strong>{contract?.reference||"Dossier contractuel"}</strong><span>{contract?.title||"Aucun contrat sélectionné"}</span></div></div><RecordList rows={rows} empty="Aucun enregistrement disponible" fields={["event_type","status","decision","reason","reference","created_at"]}/><div className={styles.modalFooter}><button onClick={()=>window.print()}>Imprimer la vue</button></div></div>}

function Kpi({icon,label:lbl,value,hint,tone:t}:any){return <article className={`${styles.kpi} ${styles[`kpi_${t}`]}`}><div className={styles.kpiIcon}>{icon}</div><div><span>{lbl}</span><strong>{value}</strong><p>{hint}</p></div></article>}
function Panel({title,subtitle,icon,children,className=""}:any){return <article className={`${styles.panel} ${className}`}><div className={styles.panelHeader}><div className={styles.panelIcon}>{icon}</div><div><h3>{title}</h3><p>{subtitle}</p></div></div><div className={styles.panelBody}>{children}</div></article>}
function Status({value}:any){return <span className={`${styles.status} ${tone(value)}`}>{label(value)}</span>}
function Empty({title,text}:any){return <div className={styles.empty}><Sparkles size={22}/><strong>{title}</strong><p>{text}</p></div>}
function LoadingState(){return <div className={styles.state}><RefreshCw className={styles.spin} size={25}/><h2>Préparation du contrôle contractuel</h2><p>Synchronisation des contrats, signatures, paiements, gates, obligations et preuves de réalisation.</p></div>}
function ErrorState({message,onRetry}:any){return <div className={styles.state}><AlertTriangle size={26}/><h2>Le contrôle contractuel n’a pas pu être chargé</h2><p>{message}</p><button onClick={onRetry}>Réessayer</button></div>}
function Timeline({rows}:any){return <div className={styles.timeline}>{rows.map((row:any,index:number)=><div key={row.id||index}><span/><div><strong>{label(row.event_type||row.to_status||row.status||row.decision)}</strong><p>{row.reason||row.title||row.reference||"Événement contractuel"}</p><time>{date(row.created_at||row.occurred_at||row.realized_at)}</time></div></div>)}{!rows.length&&<Empty title="Historique vide" text="Les transitions futures apparaîtront ici."/>}</div>}
function GateSummary({data}:any){return <div className={styles.gateSummary}><GateLine label="Approbations" value={data.summary.approval} total={data.summary.total}/><GateLine label="Signatures" value={data.summary.fullySigned} total={data.summary.total}/><GateLine label="Paiement confirmé" value={data.summary.paymentConfirmedMad} total={data.summary.contractValueMad} money/><GateLine label="Activation prête" value={data.summary.activationReady} total={data.summary.total}/></div>}
function GateLine({label:lbl,value,total,money}:any){const ratio=total?Math.max(0,Math.min(100,Number(value||0)/Number(total||1)*100)):0;return <div className={styles.gateLine}><div><span>{lbl}</span><b>{money?dh(value):value}</b></div><div><span style={{width:`${ratio}%`}}/></div></div>}
function MiniBars({items}:any){const max=Math.max(1,...items.map((x:any)=>Number(x[1]||0)));return <div className={styles.miniBars}>{items.map((item:any)=><div key={item[0]}><span>{item[0]}</span><div><i style={{width:`${Math.max(4,Number(item[1]||0)/max*100)}%`}}/></div><b>{item[1]}</b></div>)}</div>}
function ValueStack({items}:any){return <div className={styles.valueStack}>{items.map((item:any)=><div key={item[0]}><span>{item[0]}</span><strong>{dh(item[1])}</strong></div>)}</div>}
function ContractMiniDossier({contract,open}:any){return <div className={styles.miniDossier}><div className={styles.dossierHead}><div><span>{contract.reference||"CONTRAT"}</span><strong>{contract.title}</strong><p>{contract.entity_name||contract.account_name||"Compte relié"}</p></div><b>{dh(contract.contract_value)}</b></div><div className={styles.dossierStatuses}><Status value={contract.status}/><Status value={contract.signature_status}/><Status value={contract.payment_gate_status}/><Status value={contract.activation_status}/></div><DefinitionList items={[['Propriétaire',contract.owner||'—'],['Effet',date(contract.effective_date)],['Expiration',date(contract.expiry_date)],['Revenu réalisé',dh(contract.realized_value)],['Action',contract.next_action||'—']]}/><div className={styles.dossierActions}><button onClick={()=>open('signature-history',contract)}>Signatures</button><button onClick={()=>open('payment-history',contract)}>Paiements</button><button onClick={()=>open('contract-audit',contract)}>Audit</button></div></div>}
function DefinitionList({items}:any){return <dl className={styles.definitionList}>{items.map((item:any)=><div key={item[0]}><dt>{item[0]}</dt><dd>{item[1]}</dd></div>)}</dl>}
function GateCards({rows}:any){return <div className={styles.gateCards}>{rows.map((row:any,index:number)=><div key={`${row[0]}-${index}`}><span className={`${styles.gateIndicator} ${tone(row[1])}`}/><div><strong>{label(row[0])}</strong><p>{label(row[1])}</p></div></div>)}</div>}
function RecordList({rows,empty,fields}:any){return <div className={styles.recordList}>{rows.slice(0,16).map((row:any,index:number)=><div key={row.id||index}>{fields.map((field:string,i:number)=>i===0?<strong key={field}>{formatField(field,row[field])}</strong>:<span key={field}>{formatField(field,row[field])}</span>)}</div>)}{!rows.length&&<Empty title={empty} text="Les enregistrements créés par le workflow apparaîtront ici."/>}</div>}
function formatField(field:string,value:any){if(value==null||value==="")return "—";if(/amount|value|deposit/.test(field))return dh(value);if(/date|_at/.test(field))return date(value);if(typeof value==="boolean")return value?"Oui":"Non";return label(value)}
function StudioSection({title,description,actions,children}:any){return <div className={styles.studioSection}><div className={styles.studioSectionHeader}><div><h3>{title}</h3><p>{description}</p></div>{actions&&<div className={styles.actionRow}>{actions}</div>}</div>{children}</div>}
function ContractDocument({contract}:any){return <div className={styles.contractPaper}><div className={styles.paperTop}><div className={styles.brandMark}><span>▲</span><strong>ANGELCARE</strong></div><div><span>{contract.reference}</span><strong>{contract.title}</strong></div></div><h3>Objet et portée contractuelle</h3><p>Le présent espace compose une représentation structurée du contrat. Les clauses client, obligations, conditions financières et modalités d’activation doivent être validées avant création d’une version immuable.</p><div className={styles.paperGrid}><div><span>Valeur</span><strong>{dh(contract.contract_value)}</strong></div><div><span>Date d’effet</span><strong>{date(contract.effective_date)}</strong></div><div><span>Expiration</span><strong>{date(contract.expiry_date)}</strong></div><div><span>État</span><strong>{label(contract.status)}</strong></div></div><div className={styles.paperSignature}><span>ANGELCARE — signature autorisée</span><span>Contrepartie — signature vérifiée</span></div></div>}
function SignatoryMatrix({rows}:any){return <div className={styles.signatoryMatrix}>{rows.map((row:any,index:number)=><div key={row.id||index}><span className={`${styles.avatar} ${tone(row.status)}`}>{String(row.name||'?').slice(0,1).toUpperCase()}</span><div><strong>{row.name}</strong><p>{row.role} · {label(row.party_type)}</p></div><b>#{row.signing_order||index+1}</b><Status value={row.status}/></div>)}{!rows.length&&<Empty title="Aucun signataire défini" text="Ajoutez les signataires internes et externes dans leur ordre exact."/>}</div>}
function GateRecords({title,rows}:any){return <div className={styles.gateRecords}><h4>{title}</h4>{rows.slice(0,5).map((row:any,index:number)=><div key={row.id||index}><span className={`${styles.statusDot} ${tone(row.status)}`}/><strong>{row.title||row.schedule_type||row.reference||row.finance_reference||row.expected_amount||'Élément'}</strong><span>{row.amount?dh(row.amount):date(row.due_date||row.promised_date||row.payment_date)}</span><Status value={row.status}/></div>)}{!rows.length&&<p>Aucun élément</p>}</div>}
function gateScore(contract:any,gates:any[]){const own=gates.filter(g=>g.contract_id===contract.id);if(!own.length)return 0;return Math.round(own.filter(g=>g.status==="passed").length/own.length*100)}
function ExecutiveMetric({icon,value,label:lbl}:any){return <div><span>{icon}</span><strong>{value}</strong><p>{lbl}</p></div>}
function FormGrid({children}:any){return <div className={styles.formGrid}>{children}</div>}
function Input({label:lbl,wide,...rest}:any){return <div className={`${styles.field} ${wide?styles.fieldWide:""}`}><label>{lbl}</label><input {...rest}/></div>}
function Textarea({label:lbl,wide,...rest}:any){return <div className={`${styles.field} ${wide?styles.fieldWide:""}`}><label>{lbl}</label><textarea {...rest}/></div>}
function Select({label:lbl,options,...rest}:any){return <div className={styles.field}><label>{lbl}</label><select {...rest}>{options.map((item:string)=><option key={item} value={item}>{label(item)}</option>)}</select></div>}
function RecordSelect({label:lbl,records,labelKeys,...rest}:any){return <div className={styles.field}><label>{lbl}</label><select {...rest} required><option value="">Sélectionner…</option>{records.map((record:any)=><option key={record.id} value={record.id}>{labelKeys.map((key:string)=>formatField(key,record[key])).filter(Boolean).join(" · ")}</option>)}</select></div>}
